"use client"

import { useState, useEffect } from "react"
import { walletManager } from "./wallet-manager"

export function useWallet() {
  const [account, setAccount] = useState<string | null>(null)
  const [isConnected, setIsConnected] = useState(false)
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    // Check if already connected
    const initializeWallet = async () => {
      try {
        // First, try to restore from localStorage (page refresh)
        const storedAccount = typeof window !== "undefined" ? localStorage.getItem("connectedAccount") : null
        const wasConnected = typeof window !== "undefined" ? localStorage.getItem("isConnected") === "true" : false
        
        if (storedAccount && wasConnected) {
          console.log("[v0] Restoring wallet from localStorage...")
          setAccount(storedAccount)
          setIsConnected(true)
          
          // Try to reconnect to MetaMask if available
          if ((window as any).ethereum) {
            try {
              const accounts = await (window as any).ethereum.request({ method: "eth_accounts" })
              if (accounts && accounts.length > 0) {
                console.log("[v0] MetaMask reconnected:", accounts[0])
                setAccount(accounts[0])
                setIsConnected(true)
              }
            } catch (err) {
              console.log("[v0] Could not auto-reconnect to MetaMask, using stored account")
            }
          }
          return
        }
        
        // Fall back to getCurrentUser if no localStorage
        const currentUser = walletManager.getCurrentUser()
        if (currentUser) {
          setAccount(currentUser)
          setIsConnected(true)
        }
      } catch (err) {
        console.error("[v0] Wallet initialization error:", err)
      }
    }

    initializeWallet()
  }, [])

  const connectWallet = async () => {
    setIsLoading(true)
    setError(null)
    try {
      const address = await walletManager.connectWallet()
      setAccount(address)
      setIsConnected(true)
    } catch (err: any) {
      setError(err.message)
      setIsConnected(false)
    } finally {
      setIsLoading(false)
    }
  }

  const disconnectWallet = () => {
    walletManager.disconnectWallet()
    setAccount(null)
    setIsConnected(false)
    setError(null)
  }

  return {
    account,
    isConnected,
    isLoading,
    error,
    connectWallet,
    disconnectWallet,
    walletManager,
  }
}
